analyze.mjs.text:
// Classifies a set of probe results (real HTTP responses, collected by
// probe.mjs's live requests, or pasted in by hand) into a verdict about
// whether Firebase's Realtime Database or Firestore security rules allow an
// unauthenticated request to read real data.
//
// Pure function, no I/O, no network -- imported identically by the CLI
// (check.mjs, which fetches for real) and the browser page (index.html,
// which can fetch for real too, for the Realtime Database half -- see
// probe.mjs's header comment for the Firestore/CORS caveat).
//
// What each classification means, in Firebase's own terms:
//
//   exposed   The request returned real data to a plain, unauthenticated
//             GET: for the Realtime Database, at least one child key at the
//             probed path; for Firestore, at least one document in the
//             collection. This is the "default-open" / left-in-test-mode
//             shape documented since Appthority's 2018 "Firebase
//             mismanagement" report and recurring in security research
//             since -- security rules that read `allow read, write: if
//             true;` (or Realtime Database's equivalent `".read": true`),
//             either left over from test mode or hand-written that way.
//   blocked   HTTP 401/403 (Realtime Database) or 403 PERMISSION_DENIED
//             (Firestore) -- rules rejected the unauthenticated request
//             outright. This is the healthy outcome.
//   unconfirmed  HTTP 200 with no data: the Realtime Database path is
//             `null`, or the Firestore collection returned zero documents.
//             Genuinely ambiguous -- the same response whether the rules
//             are correctly blocking every read or the path/collection is
//             simply empty. Reported as its own category rather than
//             folded into either "exposed" or "blocked", because claiming
//             either from this response alone would be a guess.
//   error     The request itself did not complete cleanly (network error,
//             timeout, malformed response, a status this tool does not
//             classify). Never read as either finding.

function classifyRealtimeDatabase(result) {
  if (!result) return null;
  if (result.ok === false && result.status == null) {
    return { source: 'realtime-database', path: result.path, category: 'error', status: null, keyCount: 0, keys: [], error: result.error ?? 'request failed' };
  }
  const status = result.status ?? null;
  if (status === 401 || status === 403) {
    return { source: 'realtime-database', path: result.path, category: 'blocked', status, keyCount: 0, keys: [], error: null };
  }
  if (status != null && status >= 200 && status < 300) {
    const keys = result.keys ?? [];
    if (result.isNull || keys.length === 0) {
      return { source: 'realtime-database', path: result.path, category: 'unconfirmed', status, keyCount: 0, keys: [], error: null };
    }
    return { source: 'realtime-database', path: result.path, category: 'exposed', status, keyCount: keys.length, keys, error: null };
  }
  return { source: 'realtime-database', path: result.path, category: 'error', status, keyCount: 0, keys: [], error: result.error ?? `unexpected HTTP ${status}` };
}

function classifyFirestoreCollection(result) {
  const collection = result?.collection ?? '(unknown collection)';
  if (!result || (result.ok === false && result.status == null)) {
    return { source: 'firestore', collection, category: 'error', status: null, documentCount: 0, fieldNames: [], error: result?.error ?? 'request failed' };
  }
  const status = result.status ?? null;
  if (status === 401 || status === 403) {
    return { source: 'firestore', collection, category: 'blocked', status, documentCount: 0, fieldNames: [], error: null };
  }
  if (status != null && status >= 200 && status < 300) {
    const documentCount = result.documentCount ?? 0;
    if (documentCount === 0) {
      return { source: 'firestore', collection, category: 'unconfirmed', status, documentCount: 0, fieldNames: [], error: null };
    }
    return { source: 'firestore', collection, category: 'exposed', status, documentCount, fieldNames: result.fieldNames ?? [], error: null };
  }
  return { source: 'firestore', collection, category: 'error', status, documentCount: 0, fieldNames: [], error: result.error ?? `unexpected HTTP ${status}` };
}

/**
 * @param {object} probeResult - the object returned by probe.mjs's
 *   `runProbes` (or the CLI's pasted-in equivalent):
 *   `{ projectId, databaseUrl, realtimeDatabase, firestore, truncated }`
 */
export function buildReport(probeResult) {
  const { projectId = null, databaseUrl = null, realtimeDatabase = null, firestore = [], truncated = false } = probeResult ?? {};

  const rtdbClassified = classifyRealtimeDatabase(realtimeDatabase);
  const firestoreClassified = (Array.isArray(firestore) ? firestore : []).map(classifyFirestoreCollection);
  const classified = [rtdbClassified, ...firestoreClassified].filter(Boolean);

  const findings = classified
    .filter((c) => c.category === 'exposed')
    .map((c) =>
      c.source === 'realtime-database'
        ? {
            id: 'realtime-database-path-readable',
            severity: 'danger',
            location: `Realtime Database path "${c.path}"`,
            title: `Realtime Database path "${c.path}" is readable by anyone, with no login`,
            detail:
              `${c.keyCount} child key(s) returned to an unauthenticated request with no session, no ID token, ` +
              `and no server of ours involved -- the same request any visitor's browser (or curl) can send. ` +
              `Key names visible: ${c.keys.join(', ')}.`,
            evidenceStatus: `HTTP ${c.status}, shallow=true`,
          }
        : {
            id: 'firestore-collection-readable',
            severity: 'danger',
            location: `Firestore collection "${c.collection}"`,
            title: `Firestore collection "${c.collection}" is readable by anyone, with no login`,
            detail:
              `${c.documentCount} document(s) returned to an unauthenticated request with no session, no ID token, ` +
              `and no server of ours involved. ` +
              (c.fieldNames.length > 0 ? `Field names visible on the first document: ${c.fieldNames.join(', ')}.` : ''),
            evidenceStatus: `HTTP ${c.status}, pageSize=1`,
          },
    );

  const unconfirmed = classified.filter((c) => c.category === 'unconfirmed');
  const blocked = classified.filter((c) => c.category === 'blocked');
  const errors = classified.filter((c) => c.category === 'error');

  return {
    projectId,
    databaseUrl,
    checked: classified.length,
    truncated: Boolean(truncated),
    classified,
    findings,
    unconfirmed,
    blocked,
    errors,
    dangerCount: findings.length,
    ok: findings.length === 0 && classified.length > 0,
    incomplete: errors.length > 0 || classified.length === 0,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: sends real, read-only, unauthenticated requests to a Firebase
// project's Realtime Database (shallow key listing) and/or named Firestore
// collections (one document max per collection), and reports which paths
// return real data to that request -- the "default-open" / left-in-test-mode
// security-rules exposure. Your machine, the project's own REST endpoints --
// no request goes through this portfolio.
//
//   node check.mjs <project-id> [--database-url <url>] [--collection <name>]...
//                   [--api-key <key>] [--json] [--timeout <ms>]
//
// Only run this against a Firebase project you own or are authorised to
// test. This never writes, updates, or deletes anything -- every request is
// GET, and the Realtime Database probe uses `shallow=true`, which returns
// child key names only, never field values.
//
// Exit code 0 when at least one path/collection was checked and none
// returned real data to the unauthenticated request; 1 when at least one is
// exposed or nothing could be checked at all.

import { runProbes } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Project: ${report.projectId}`);
  if (report.databaseUrl) lines.push(`Realtime Database: ${report.databaseUrl}`);
  lines.push(`Paths/collections checked: ${report.checked}${report.truncated ? ' (list truncated at the cap)' : ''}`);
  lines.push('');

  if (report.checked === 0) {
    lines.push('Nothing to check -- pass --database-url and/or one or more --collection names.');
    return lines.join('\n');
  }

  if (report.findings.length === 0) {
    lines.push('No path or collection returned real data to an unauthenticated request.');
  } else {
    for (const f of report.findings) {
      lines.push(`!! [DANGER] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     evidence: ${f.evidenceStatus}`);
      lines.push('');
    }
  }

  if (report.unconfirmed.length > 0) {
    lines.push('');
    lines.push(
      `${report.unconfirmed.length} path/collection returned zero rows with no way to tell "rules are blocking this" ` +
        'from "this is just empty": ' +
        report.unconfirmed.map((c) => (c.source === 'realtime-database' ? c.path : c.collection)).join(', ') +
        '. Insert one throwaway test value (or check the Firebase console Rules Playground) to resolve which.',
    );
  }
  if (report.errors.length > 0) {
    lines.push('');
    lines.push(`${report.errors.length} path/collection could not be checked: ${report.errors.map((c) => `${c.source === 'realtime-database' ? c.path : c.collection} (${c.error})`).join('; ')}`);
  }
  if (report.blocked.length > 0) {
    lines.push('');
    lines.push(`${report.blocked.length} path/collection correctly rejected this unauthenticated request: ${report.blocked.map((c) => (c.source === 'realtime-database' ? c.path : c.collection)).join(', ')}`);
  }

  lines.push('');
  lines.push('This is evidence from the requests above, not a full security audit -- see README.md for what this tool does and does not check.');
  return lines.join('\n');
}

function parseArgs(argv) {
  const args = { projectId: null, databaseUrl: null, collections: [], apiKey: null, json: false, timeoutMs: undefined };
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--json') args.json = true;
    else if (a === '--timeout') args.timeoutMs = Number(argv[++i]);
    else if (a === '--database-url') args.databaseUrl = argv[++i];
    else if (a === '--collection') args.collections.push(argv[++i]);
    else if (a === '--api-key') args.apiKey = argv[++i];
    else if (!a.startsWith('--')) positional.push(a);
  }
  args.projectId = positional[0] ?? null;
  return args;
}

/** Pure orchestration: given a probe function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `probeFn` instead of hitting the network. */
export async function runCheck(projectId, opts = {}) {
  const { probeFn = runProbes, timeoutMs, ...probeOpts } = opts;
  const probeResult = await probeFn(projectId, { ...probeOpts, ...(timeoutMs ? { timeoutMs } : {}) });
  return buildReport(probeResult);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.projectId) {
    console.error('Usage: node check.mjs <project-id> [--database-url <url>] [--collection <name>]... [--api-key <key>] [--json] [--timeout <ms>]');
    console.error('Only run this against a Firebase project you own or are authorised to test.');
    process.exit(2);
  }
  if (!args.databaseUrl && args.collections.length === 0) {
    console.error('Nothing to check -- pass --database-url and/or one or more --collection names.');
    process.exit(2);
  }

  const report = await runCheck(args.projectId, {
    databaseUrl: args.databaseUrl,
    collections: args.collections,
    apiKey: args.apiKey ?? undefined,
    timeoutMs: args.timeoutMs,
  });

  if (args.json) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Sends the real HTTP requests this check depends on, using the global
// `fetch` -- the same module runs unmodified from the CLI (Node 22's
// built-in fetch) and from the browser page (index.html imports it
// directly). Firebase's Realtime Database REST API is documented and
// designed to be called directly with plain HTTP from a browser tab (the
// `.json` suffix convention exists for exactly that), so a visitor's own
// browser can run the real Realtime Database check with no server of ours
// in the middle. The Firestore REST endpoint (firestore.googleapis.com) is
// less certain to answer a cross-origin browser fetch with the right CORS
// headers in every project configuration -- if a visitor's browser reports
// a network or CORS error on the Firestore half, index.html says so and
// points at the identical CLI check, which is never subject to browser CORS
// restrictions.
//
// Every request here goes only to the one Firebase project a caller names
// (its Realtime Database URL and/or its Firestore project ID), and only
// ever with a plain, unauthenticated GET -- the same request Firebase's own
// REST documentation describes as the normal, unauthenticated shape a
// request takes when no ID token is attached. This module makes no other
// network call, reads no local files, and sends nothing anywhere else.
//
// Firebase has no equivalent of PostgREST's schema-listing endpoint for
// Firestore, so unlike ventures/supabase-rls-check this module cannot
// discover collection names on its own -- the caller supplies the
// collection names to check (the same "I already know what to check"
// fallback path supabase-rls-check's own runProbes offers via its
// `tables` option). The Realtime Database half needs no such list: a
// `shallow=true` request against any path returns only the immediate child
// key names with no field values at all, so the root of the tree can be
// probed directly.

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'firebase-rules-check/1 (+https://duncan-haywood.github.io/monorepo-projects/firebase-rules-check/)';

function normalizeDatabaseUrl(databaseUrl) {
  const trimmed = String(databaseUrl || '').trim().replace(/\/+$/, '');
  const parsed = new URL(trimmed);
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {
    throw new Error(`unsupported scheme: ${parsed.protocol}`);
  }
  return parsed.origin + parsed.pathname.replace(/\/+$/, '');
}

function normalizeProjectId(projectId) {
  const trimmed = String(projectId || '').trim();
  if (!/^[a-z0-9][a-z0-9-]{2,62}$/.test(trimmed)) {
    throw new Error(`not a plausible Firebase project ID: ${JSON.stringify(projectId)}`);
  }
  return trimmed;
}

async function timedFetch(url, init, timeoutMs, fetchImpl) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (typeof doFetch !== 'function') {
    throw new Error('no fetch implementation available in this environment');
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await doFetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Probes one path in a Realtime Database with `shallow=true`, which Firebase
 * documents to return only the immediate child key names (each as the
 * literal value `true`) and never the actual field values underneath them --
 * enough to tell whether the path is readable by an unauthenticated request
 * without ever downloading real data.
 */
export async function probeRealtimeDatabasePath(databaseUrl, path, { timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl } = {}) {
  const base = normalizeDatabaseUrl(databaseUrl);
  const cleanPath = String(path || '').replace(/^\/+|\/+$/g, '');
  const url = `${base}/${cleanPath}.json?shallow=true`;
  let res;
  try {
    res = await timedFetch(url, { method: 'GET', headers: { 'user-agent': USER_AGENT, accept: 'application/json' } }, timeoutMs, fetchImpl);
  } catch (err) {
    return { path: cleanPath || '/', ok: false, status: null, keys: null, error: err.message ?? String(err) };
  }
  let body;
  let parseError = null;
  try {
    const text = await res.text();
    body = text.length > 0 ? JSON.parse(text) : null;
  } catch (err) {
    parseError = err.message ?? String(err);
  }
  return {
    path: cleanPath || '/',
    ok: res.ok,
    status: res.status,
    keys: res.ok && body && typeof body === 'object' ? Object.keys(body) : res.ok ? [] : null,
    isNull: res.ok && body === null,
    error: !res.ok ? `HTTP ${res.status}` : parseError,
  };
}

/**
 * Requests up to one document from a Firestore collection with
 * `pageSize=1`. Never reads more than one document, and the report built
 * from this result (`analyze.mjs`) only ever surfaces field *names*, not
 * field values -- the same "evidence, not a data dump" posture
 * `ventures/supabase-rls-check` uses.
 */
export async function probeFirestoreCollection(projectId, collectionPath, { timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl, apiKey } = {}) {
  const project = normalizeProjectId(projectId);
  const cleanPath = String(collectionPath || '').replace(/^\/+|\/+$/g, '');
  const query = new URLSearchParams({ pageSize: '1' });
  if (apiKey) query.set('key', apiKey);
  const url = `https://firestore.googleapis.com/v1/projects/${encodeURIComponent(project)}/databases/(default)/documents/${cleanPath
    .split('/')
    .map(encodeURIComponent)
    .join('/')}?${query.toString()}`;
  let res;
  try {
    res = await timedFetch(url, { method: 'GET', headers: { 'user-agent': USER_AGENT, accept: 'application/json' } }, timeoutMs, fetchImpl);
  } catch (err) {
    return { collection: cleanPath, ok: false, status: null, documentCount: 0, fieldNames: [], error: err.message ?? String(err) };
  }
  let body;
  let parseError = null;
  try {
    body = await res.json();
  } catch (err) {
    parseError = err.message ?? String(err);
  }
  const documents = Array.isArray(body?.documents) ? body.documents : [];
  const fieldNames = documents.length > 0 && documents[0]?.fields && typeof documents[0].fields === 'object' ? Object.keys(documents[0].fields) : [];
  const apiError = !res.ok ? (body?.error?.message ? `HTTP ${res.status}: ${body.error.message}` : `HTTP ${res.status}`) : parseError;
  return { collection: cleanPath, ok: res.ok, status: res.status, documentCount: documents.length, fieldNames, error: apiError };
}

/**
 * Full run: Realtime Database root (if a `databaseUrl` was given), then one
 * probe per Firestore collection name in `collections` (if any). Either
 * input may be omitted -- a project may use only one of the two products.
 */
export async function runProbes(projectId, { databaseUrl, collections = [], apiKey, timeoutMs, fetchImpl, maxCollections = 50 } = {}) {
  const realtimeDatabase = databaseUrl
    ? await probeRealtimeDatabasePath(databaseUrl, '/', { timeoutMs, fetchImpl })
    : null;

  const capped = collections.slice(0, maxCollections);
  const firestore = await Promise.all(
    capped.map((collection) => probeFirestoreCollection(projectId, collection, { timeoutMs, fetchImpl, apiKey })),
  );

  return {
    projectId,
    databaseUrl: databaseUrl ? normalizeDatabaseUrl(databaseUrl) : null,
    realtimeDatabase,
    firestore,
    truncated: collections.length > capped.length,
  };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// project ID, the database URL, the collection names, or anything about
// what came back -- that is exactly the kind of thing that must not be
// transmitted or retained anywhere, and this tool never reads it off the
// visitor's machine either.

const STORAGE_KEY = 'firebase-rules-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters: opting out
// *removes* the counters, so a flag stored inside them would be deleted by
// the very act it records.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
